                Reservation reservation = repository.getReservation(id);
                if (reservation == null) {
                    ctx.status(HttpStatus.NOT_FOUND);
                    ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
                    return;
